import { useState } from 'react'
import { useCart } from '../context/CartContext'

function formatEUR(cents) {
  return new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(cents / 100)
}

export default function ProductCard({ product }) {
  const { addItem } = useCart()
  const [added, setAdded] = useState(false)
  const { name, description, price, image_url, tags, is_available } = product

  function handleAddToCart() {
    if (!is_available) return
    addItem(product, 1)
    setAdded(true)
    setTimeout(() => setAdded(false), 1500)
  }

  return (
    <article
      className={`flex flex-col rounded-2xl overflow-hidden border border-[#e5e5e5] bg-white transition-opacity duration-200 ${
        is_available ? 'opacity-100' : 'opacity-50'
      }`}
    >
      {/* Full-bleed image — 4:3 aspect ratio */}
      <div className="relative w-full" style={{ paddingTop: '75%' }}>
        {image_url ? (
          <img
            src={image_url}
            alt={name}
            className="absolute inset-0 w-full h-full object-cover"
          />
        ) : (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-100 text-gray-400 text-sm">
            No image
          </div>
        )}
        {!is_available && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/30">
            <span className="bg-white text-[#1a1a1a] text-xs font-semibold px-3 py-1 rounded-full">
              Unavailable
            </span>
          </div>
        )}
      </div>

      {/* Card body */}
      <div className="flex flex-col flex-1 p-4 gap-2">
        <h2 className="text-base font-bold text-[#1a1a1a] leading-snug line-clamp-2">{name}</h2>

        {description && (
          <p className="text-sm text-gray-500 line-clamp-3 flex-1">{description}</p>
        )}

        {tags && tags.length > 0 && (
          <div className="flex flex-wrap gap-1 mt-1">
            {tags.map(tag => (
              <span
                key={tag}
                className="text-xs bg-gray-100 text-gray-500 rounded-full px-2 py-0.5"
              >
                {tag}
              </span>
            ))}
          </div>
        )}

        <div className="flex items-center justify-between mt-3">
          <span className="text-lg font-bold text-[#1a1a1a]">{formatEUR(price)}</span>
          <button
            onClick={handleAddToCart}
            disabled={!is_available}
            className={`text-sm font-semibold px-4 py-2 rounded-full transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-[#ff90e8] ${
              is_available
                ? added
                  ? 'bg-green-500 text-white cursor-default'
                  : 'bg-[#ff90e8] text-[#1a1a1a] hover:opacity-80'
                : 'bg-gray-100 text-gray-400 cursor-not-allowed'
            }`}
          >
            {added ? 'Added ✓' : 'Add to cart'}
          </button>
        </div>
      </div>
    </article>
  )
}

import { useEffect, useRef, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { useCart } from '../context/CartContext'

function formatEUR(cents) {
  return new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(cents / 100)
}

function QtyButton({ onClick, disabled, children, ariaLabel }) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      aria-label={ariaLabel}
      className="w-7 h-7 flex items-center justify-center rounded-full border border-[#e5e5e5] text-[#1a1a1a] text-base font-bold transition-colors hover:bg-gray-100 disabled:opacity-30 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-[#ff90e8]"
    >
      {children}
    </button>
  )
}

function CartItem({ item, onRemove, onUpdateQty }) {
  return (
    <li className="flex items-start gap-3 py-4 border-b border-[#e5e5e5] last:border-0">
      <div className="w-16 h-16 flex-shrink-0 rounded-xl overflow-hidden bg-gray-100">
        {item.image_url ? (
          <img src={item.image_url} alt={item.name} className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-gray-300 text-2xl">🖼</div>
        )}
      </div>

      <div className="flex-1 min-w-0">
        <p className="text-sm font-bold text-[#1a1a1a] truncate">{item.name}</p>
        <p className="text-xs text-gray-500 mt-0.5">{formatEUR(item.price)} each</p>

        {/* Quantity controls */}
        <div className="flex items-center gap-2 mt-2">
          <QtyButton
            onClick={() => onUpdateQty(item.id, item.quantity - 1)}
            disabled={item.quantity === 1}
            ariaLabel={`Decrease quantity of ${item.name}`}
          >
            −
          </QtyButton>
          <span className="text-sm font-semibold text-[#1a1a1a] w-5 text-center" aria-live="polite">
            {item.quantity}
          </span>
          <QtyButton
            onClick={() => onUpdateQty(item.id, item.quantity + 1)}
            ariaLabel={`Increase quantity of ${item.name}`}
          >
            +
          </QtyButton>
        </div>

        {/* Line total */}
        <p className="text-sm font-bold text-[#1a1a1a] mt-1">{formatEUR(item.price * item.quantity)}</p>
      </div>

      <button
        onClick={() => onRemove(item.id)}
        aria-label={`Remove ${item.name} from cart`}
        className="flex-shrink-0 p-1 rounded-full hover:bg-red-50 text-gray-400 hover:text-red-500 transition-colors"
      >
        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>
    </li>
  )
}

export default function CartDrawer({ isOpen, onClose }) {
  const { items, total, removeItem, updateQuantity } = useCart()
  const navigate = useNavigate()
  const drawerRef = useRef(null)

  useEffect(() => {
    if (!isOpen) return
    const handleKeyDown = (e) => { if (e.key === 'Escape') onClose() }
    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [isOpen, onClose])

  useEffect(() => {
    document.body.style.overflow = isOpen ? 'hidden' : ''
    return () => { document.body.style.overflow = '' }
  }, [isOpen])

  const handleOverlayClick = useCallback((e) => {
    if (drawerRef.current && !drawerRef.current.contains(e.target)) onClose()
  }, [onClose])

  const handleCheckout = () => {
    onClose()
    navigate('/checkout')
  }

  return (
    <>
      <div
        aria-hidden={!isOpen}
        onClick={handleOverlayClick}
        className={`fixed inset-0 z-40 bg-black/40 transition-opacity duration-300 ${
          isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'
        }`}
      />

      <div
        ref={drawerRef}
        role="dialog"
        aria-modal="true"
        aria-label="Shopping cart"
        className={`fixed top-0 right-0 z-50 h-full w-full max-w-sm bg-white flex flex-col transform transition-transform duration-300 ease-in-out ${
          isOpen ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-[#e5e5e5]">
          <h2 className="text-base font-bold text-[#1a1a1a]">Your Cart</h2>
          <button
            onClick={onClose}
            aria-label="Close cart"
            className="p-2 rounded-full hover:bg-gray-100 text-gray-400 hover:text-[#1a1a1a] transition-colors"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* Items */}
        <div className="flex-1 overflow-y-auto px-5">
          {items.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-center gap-3 py-16">
              <span className="text-5xl">🛒</span>
              <p className="text-gray-500 text-sm">Your cart is empty.<br />Browse the gallery to add items!</p>
            </div>
          ) : (
            <ul>
              {items.map((item) => (
                <CartItem
                  key={item.id}
                  item={item}
                  onRemove={removeItem}
                  onUpdateQty={updateQuantity}
                />
              ))}
            </ul>
          )}
        </div>

        {/* Footer */}
        {items.length > 0 && (
          <div className="border-t border-[#e5e5e5] px-5 py-4 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-sm text-gray-500 font-medium">Total</span>
              <span className="text-base font-bold text-[#1a1a1a]" aria-live="polite">{formatEUR(total)}</span>
            </div>
            <button
              onClick={handleCheckout}
              className="w-full bg-[#ff90e8] text-[#1a1a1a] py-3 rounded-full font-bold hover:opacity-80 active:scale-95 transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#ff90e8]"
            >
              Go to Checkout
            </button>
          </div>
        )}
      </div>
    </>
  )
}

import React from 'react'

export function TagPills({ tags, selectedTags, onToggle }) {
  if (!tags || tags.length === 0) return null

  return (
    <div className="flex flex-wrap gap-2" role="group" aria-label="Filter by tag">
      {tags.map((tag) => {
        const isActive = selectedTags.includes(tag)
        return (
          <button
            key={tag}
            onClick={() => onToggle(tag)}
            aria-pressed={isActive}
            className={`rounded-full px-3 py-1 text-sm font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-[#ff90e8]/60 ${
              isActive
                ? 'bg-[#1a1a1a] text-white'
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            {tag}
          </button>
        )
      })}
      {selectedTags.length > 0 && (
        <button
          onClick={() => selectedTags.forEach((t) => onToggle(t))}
          className="rounded-full px-3 py-1 text-sm font-medium text-gray-400 hover:text-[#1a1a1a] underline"
          aria-label="Clear all tag filters"
        >
          Clear
        </button>
      )}
    </div>
  )
}

import { useState, useMemo } from 'react'
import { useProducts } from '../hooks/useProducts'
import ProductCard from '../components/ProductCard'
import MostLoved from '../components/MostLoved'
import SeasonalBanner from '../components/SeasonalBanner'
import { SearchBar } from '../components/SearchBar'
import { TagPills } from '../components/TagPills'

function SkeletonCard() {
  return (
    <div className="rounded-2xl overflow-hidden border border-[#e5e5e5] bg-white animate-pulse">
      <div style={{ paddingTop: '75%' }} className="relative bg-gray-100 w-full" />
      <div className="p-4 flex flex-col gap-3">
        <div className="h-4 bg-gray-100 rounded-full w-3/4" />
        <div className="h-3 bg-gray-100 rounded-full w-full" />
        <div className="h-3 bg-gray-100 rounded-full w-5/6" />
        <div className="flex justify-between items-center mt-2">
          <div className="h-5 bg-gray-100 rounded-full w-16" />
          <div className="h-8 bg-gray-100 rounded-full w-24" />
        </div>
      </div>
    </div>
  )
}

export default function Gallery() {
  const { products, loading, error } = useProducts()
  const [search, setSearch] = useState('')
  const [selectedTags, setSelectedTags] = useState([])

  const allTags = useMemo(() => {
    const set = new Set()
    products.forEach(p => (p.tags || []).forEach(t => set.add(t)))
    return Array.from(set).sort()
  }, [products])

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchesSearch = !search ||
        p.name.toLowerCase().includes(search.toLowerCase()) ||
        (p.description || '').toLowerCase().includes(search.toLowerCase())
      const matchesTags = selectedTags.length === 0 ||
        selectedTags.every(t => (p.tags || []).includes(t))
      return matchesSearch && matchesTags
    })
  }, [products, search, selectedTags])

  function toggleTag(tag) {
    setSelectedTags(prev =>
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    )
  }

  return (
    <main className="max-w-5xl mx-auto px-4 md:px-8 py-12">
      {/* Page heading */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-[#1a1a1a] tracking-tight">Handmade Postcards</h1>
        <p className="text-gray-500 mt-1 text-sm">Small-batch art, sent with love.</p>
      </div>

      <SeasonalBanner />
      <MostLoved />

      {/* Filters */}
      <div className="flex flex-col gap-3 mb-8">
        <SearchBar value={search} onChange={setSearch} />
        <TagPills tags={allTags} selectedTags={selectedTags} onToggle={toggleTag} />
      </div>

      {error && (
        <div className="rounded-2xl bg-red-50 border border-red-200 text-red-700 px-5 py-4 mb-6">
          <p className="font-bold">Failed to load products</p>
          <p className="text-sm mt-1">{error}</p>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
        {loading
          ? Array.from({ length: 6 }).map((_, i) => <SkeletonCard key={i} />)
          : filtered.map(product => (
              <ProductCard key={product.id} product={product} />
            ))}
      </div>

      {!loading && !error && filtered.length === 0 && (
        <div className="text-center text-gray-400 py-20">
          <p className="text-lg font-bold text-[#1a1a1a]">No postcards found.</p>
          <p className="text-sm mt-1">Try adjusting your search or filters.</p>
        </div>
      )}
    </main>
  )
}

import { useState, useEffect } from 'react'
import { loadStripe } from '@stripe/stripe-js'
import { Elements, PaymentElement, useStripe, useElements } from '@stripe/react-stripe-js'
import { useCart } from '../context/CartContext'
import { supabase } from '../lib/supabase'

const stripePromise = loadStripe(import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY)

function formatEUR(cents) {
  return new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(cents / 100)
}

function CheckoutForm({ clientSecret }) {
  const stripe = useStripe()
  const elements = useElements()
  const [error, setError] = useState(null)
  const [loading, setLoading] = useState(false)

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!stripe || !elements) return
    setLoading(true)
    setError(null)

    const { error: stripeError, paymentIntent } = await stripe.confirmPayment({
      elements,
      redirect: 'if_required',
    })

    if (stripeError) {
      setError(stripeError.message)
      setLoading(false)
      return
    }

    if (paymentIntent) {
      window.location.href = `/thank-you?payment_intent=${paymentIntent.id}`
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      <PaymentElement />
      {error && (
        <p className="text-red-600 text-sm border border-red-200 bg-red-50 rounded-xl px-4 py-2">{error}</p>
      )}
      <button
        type="submit"
        disabled={!stripe || loading}
        className="w-full bg-[#ff90e8] text-[#1a1a1a] font-bold py-3 rounded-full transition-opacity hover:opacity-80 active:scale-95 disabled:opacity-40 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#ff90e8]"
      >
        {loading ? 'Processing…' : 'Pay now'}
      </button>
    </form>
  )
}

function OrderSummary({ items }) {
  const total = items.reduce((sum, i) => sum + i.price * i.quantity, 0)
  return (
    <div className="border border-[#e5e5e5] rounded-2xl p-5 mb-6">
      <h2 className="text-sm font-bold text-[#1a1a1a] mb-3 uppercase tracking-wide">Order Summary</h2>
      <ul className="space-y-2">
        {items.map(item => (
          <li key={item.id} className="flex items-center justify-between text-sm">
            <span className="text-[#1a1a1a] font-medium">{item.name} <span className="text-gray-400">× {item.quantity}</span></span>
            <span className="font-semibold text-[#1a1a1a]">{formatEUR(item.price * item.quantity)}</span>
          </li>
        ))}
      </ul>
      <div className="border-t border-[#e5e5e5] mt-3 pt-3 flex justify-between">
        <span className="text-sm font-bold text-[#1a1a1a]">Total</span>
        <span className="text-sm font-bold text-[#1a1a1a]">{formatEUR(total)}</span>
      </div>
    </div>
  )
}

export default function Checkout() {
  const { items } = useCart()
  const [clientSecret, setClientSecret] = useState(null)
  const [error, setError] = useState(null)

  useEffect(() => {
    const total = items.reduce((sum, i) => sum + i.price * i.quantity, 0)
    supabase.functions
      .invoke('create-payment-intent', { body: { amount: total, items } })
      .then(({ data, error }) => {
        if (error) { setError(error.message); return }
        setClientSecret(data.clientSecret)
      })
  }, [])

  if (error) return (
    <div className="max-w-lg mx-auto px-4 md:px-8 py-16">
      <p className="text-red-600 border border-red-200 bg-red-50 rounded-2xl px-5 py-4">{error}</p>
    </div>
  )

  return (
    <main className="max-w-lg mx-auto px-4 md:px-8 py-12">
      <h1 className="text-2xl font-bold text-[#1a1a1a] mb-6">Checkout</h1>

      {items.length > 0 && <OrderSummary items={items} />}

      {!clientSecret ? (
        <div className="flex items-center gap-3 text-gray-400 py-8">
          <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-[#ff90e8]" />
          <span className="text-sm">Loading payment…</span>
        </div>
      ) : (
        <Elements stripe={stripePromise} options={{ clientSecret }}>
          <CheckoutForm clientSecret={clientSecret} />
        </Elements>
      )}
    </main>
  )
}

import { useEffect, useState, useRef } from 'react'
import { useSearchParams, Link } from 'react-router-dom'
import { supabase } from '../lib/supabase'

const POLL_INTERVAL_MS = 2000
const TIMEOUT_MS = 30000

function formatEUR(cents) {
  return new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(cents / 100)
}

export default function ThankYou() {
  const [searchParams] = useSearchParams()
  const paymentIntentId = searchParams.get('payment_intent')

  const [order, setOrder] = useState(null)
  const [timedOut, setTimedOut] = useState(false)
  const [error, setError] = useState(null)

  const intervalRef = useRef(null)
  const timeoutRef = useRef(null)

  const stopPolling = () => {
    clearInterval(intervalRef.current)
    clearTimeout(timeoutRef.current)
  }

  useEffect(() => {
    if (!paymentIntentId) { setError('Missing payment reference.'); return }

    const poll = async () => {
      const { data, error: dbError } = await supabase
        .from('orders')
        .select('id, stripe_payment_id, status, customer_name, total')
        .eq('stripe_payment_id', paymentIntentId)
        .eq('status', 'payment_confirmed')
        .maybeSingle()

      if (dbError) { setError(dbError.message); stopPolling(); return }
      if (data) { setOrder(data); stopPolling() }
    }

    poll()
    intervalRef.current = setInterval(poll, POLL_INTERVAL_MS)
    timeoutRef.current = setTimeout(() => { stopPolling(); setTimedOut(true) }, TIMEOUT_MS)
    return () => stopPolling()
  }, [paymentIntentId])

  if (error) return (
    <main className="max-w-lg mx-auto px-4 md:px-8 py-16">
      <div className="border border-red-200 bg-red-50 rounded-2xl px-5 py-4">
        <p className="text-red-600 text-sm">{error}</p>
      </div>
    </main>
  )

  if (order) return (
    <main className="max-w-lg mx-auto px-4 md:px-8 py-16 text-center">
      <div className="border border-[#e5e5e5] rounded-2xl p-8 space-y-4">
        <div className="text-5xl mb-2">🎉</div>
        <h1 className="text-2xl font-bold text-[#1a1a1a]">Order Confirmed!</h1>
        <p className="text-gray-500">
          Thank you, <span className="font-bold text-[#1a1a1a]">{order.customer_name}</span>!
        </p>
        <p className="text-gray-500">
          Order total: <span className="font-bold text-[#1a1a1a]">{formatEUR(order.total)}</span>
        </p>
        <p className="text-xs text-gray-400">Order ID: {order.id}</p>
        <Link
          to="/"
          className="inline-block mt-4 bg-[#1a1a1a] text-white font-bold px-6 py-3 rounded-full hover:opacity-80 transition-opacity"
        >
          Back to shop
        </Link>
      </div>
    </main>
  )

  if (timedOut) return (
    <main className="max-w-lg mx-auto px-4 md:px-8 py-16 text-center">
      <div className="border border-[#e5e5e5] rounded-2xl p-8 space-y-4">
